<?php
require __DIR__.'/../app/bootstrap.php';
$adminId=require_admin();$pdo=db();if(!db_table_exists('vacation_photo_user_limits'))redirect('upgrade.php');$policy=new VacationPhotoPolicyService($pdo);$error=null;$success=flash('success');
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();
    try{
        $action=(string)($_POST['action']??'settings');
        if($action==='settings'){$policy->saveDefaults($_POST,$adminId);flash('success','Vacation Yourself generation policy saved.');}
        elseif($action==='user_limit'){$policy->saveUserLimit((int)($_POST['user_id']??0),$_POST,$adminId);flash('success','User generation limits saved.');}
        redirect('admin/vacation-photos.php');
    }catch(Throwable $e){$error=$e->getMessage();}
}
$period=max(1,min(365,(int)($_GET['days']??30)));$stats=$policy->aggregate($period);$allStats=$policy->aggregate(null);$users=$pdo->query('SELECT u.id,u.display_name,u.email,l.daily_limit,l.monthly_limit,l.lifetime_limit,l.comped_generations,l.notes FROM users u LEFT JOIN vacation_photo_user_limits l ON l.user_id=u.id WHERE u.status="active" AND '.(db_column_exists('users','is_sample')&&!sample_data_enabled()?'u.is_sample=0':'1=1').' ORDER BY u.display_name,u.email LIMIT 500')->fetchAll();
$settings=[
'enabled'=>site_setting_bool('vacation_photos.enabled',true),'gallery_enabled'=>site_setting_bool('vacation_photos.gallery_enabled',true),'sharing_enabled'=>site_setting_bool('vacation_photos.sharing_enabled',true),'daily_limit'=>(int)site_setting('vacation_photos.daily_limit','8'),'monthly_limit'=>(int)site_setting('vacation_photos.monthly_limit','40'),'lifetime_limit'=>(int)site_setting('vacation_photos.lifetime_limit','0'),'default_quality'=>site_setting('vacation_photos.default_quality','medium'),'default_over_the_top'=>(int)site_setting('vacation_photos.default_over_the_top','35'),'max_reference_images'=>(int)site_setting('vacation_photos.max_reference_images','4')];
$costKeys=['low.square'=>'Low · square','low.large'=>'Low · landscape/portrait','medium.square'=>'Medium · square','medium.large'=>'Medium · landscape/portrait','high.square'=>'High · square','high.large'=>'High · landscape/portrait','reference_image'=>'Each reference image'];$selectedUser=max(0,(int)($_GET['user_id']??0));$selectedRow=null;foreach($users as $row)if((int)$row['id']===$selectedUser){$selectedRow=$row;break;}
$title='Vacation Yourself — Admin';require __DIR__.'/../partials/header.php';
?>
