ovider pricing and reference-image token use change.</p><div class="vp-cost-grid"><?php foreach($costKeys as $key=>$label):?><label><?=$label?><input class="input" type="number" min="0" max="10" step="0.0001" name="cost_<?=$key?>" value="<?=e(site_setting('vacation_photos.estimate.'.$key,'0'))?>"></label><?php endforeach;?></div><button class="button primary" type="submit">Save Vacation Yourself Policy</button></form>
<div><article class="dashboard-card"><h2>User overrides</h2><p class="muted">Blank values inherit global limits. Comped generations extend only a non-zero lifetime allowance.</p><div class="vp-user-list"><?php foreach($users as $row):?><div class="vp-user-row"><div><strong><?=e($row['display_name']?:'Vacation Brain User')?></strong><div class="muted small"><?=e($row['email'])?></div></div><a href="<?=e(app_url('admin/vacation-photos.php?user_id='.(int)$row['id']))?>">Limits</a></div><?php endforeach;?></div></article><?php if($selectedRow):?><form class="dashboard-card stack" style="margin-top:20px" method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="user_limit"><input type="hidden" name="user_id" value="<?=(int)$selectedRow['id']?>"><h2><?=e($selectedRow['display_name']?:$selectedRow['email'])?></h2><div class="form-grid"><label>Daily override<input class="input" type="number" min="0" name="daily_limit" value="<?=e($selectedRow['daily_limit']===null?'':(string)$selectedRow['daily_limit'])?>" placeholder="Inherit"></label><label>Monthly override<input class="input" type="number" min="0" name="monthly_limit" value="<?=e($selectedRow['monthly_limit']===null?'':(string)$selectedRow['monthly_limit'])?>" placeholder="Inherit"></label><label>Lifetime override<input class="input" type="number" min="0" name="lifetime_limit" value="<?=e($selectedRow['lifetime_limit']===null?'':(string)$selectedRow['lifetime_limit'])?>" placeholder="Inherit"></label></div><label>Comped generations<input class="input" type="number" min="0" name="comped_generations" value="<?=(int)$selectedRow['comped_generations']?>"></label><label>Notes<input class="input" name="notes" maxlength="500" value="<?=e((string)$selectedRow['notes'])?>"></label><button class="button primary">Save User Limits</button></form><?php endif;?></div></div>
<div class="dashboard-card" style="margin-top:24px"><div class="section-head"><div><span class="eyebrow">Recent generations</span><h2>Usage ledger</h2></div><form method="get"><select class="input" name="days" onchange="this.form.submit()"><?php foreach([7,30,90,365] as $d):?><option value="<?=$d?>" <?=$period===$d?'selected':''?>><?=$d?> days</option><?php endforeach;?></select></form></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>User</th><th>Destination</th><th>Quality</th><th>References</th><th>Est. cost</th><th>Created</th></tr></thead><tbody><?php foreach(array_slice($stats['rows'],0,200) as $row):$refs=json_decode((string)($row['source_refs_json']??'[]'),true)?:[];?><tr><td><strong><?=e($row['display_name']?:'User')?></strong><br><small><?=e($row['email'])?></small></td><td><?=e($row['destination'])?></td><td><?=e($row['quality'])?> · <?=e($row['size'])?></td><td><?=count($refs)?></td><td>$<?=number_format((float)$row['_estimated_cost'],4)?></td><td><?=e((string)$row['created_at'])?></td></tr><?php endforeach;?><?php if(!$stats['rows']):?><tr><td colspan="6" class="muted">No completed generations in this period.</td></tr><?php endif;?></tbody></table></div></div>
